        int bytesRead = stream.Read(buffer, 0, buffer.Length);
        string welcomeMessage = Encoding.ASCII.GetString(buffer, 0, bytesRead);
        Console.WriteLine(welcomeMessage);

        // Send the login message
        string loginMessage = "LGIN x-stream";
        byte[] loginBytes = Encoding.ASCII.GetBytes(loginMessage);
        stream.Write(loginBytes, 0, loginBytes.Length);

        // Read the response
        buffer = new byte[1024];
        bytesRead = stream.Read(buffer, 0, buffer.Length);
        string response = Encoding.ASCII.GetString(buffer, 0, bytesRead);
        Console.WriteLine(response);

        // If the password is correct, send the GTMP? message
        if (response == "Password correct")
        {
            string gtmpMessage = "GTMP?";
            byte[] gtmpBytes = Encoding.ASCII.GetBytes(gtmpMessage);
            stream.Write(gtmpBytes, 0, gtmpBytes.Length);

            // Read the temperature
            buffer = new byte[1024];
            bytesRead = stream.Read(buffer, 0, buffer.Length);
            string temperature = Encoding.ASCII.GetString(buffer, 0, bytesRead);
            Console.WriteLine(temperature);
        }

        // Send the logout message
        string logoutMessage = "LOGOUT";
        byte[] logoutBytes = Encoding.ASCII.GetBytes(logoutMessage);
        stream.Write(logoutBytes, 0, logoutBytes.Length);

        // Close the connection
        client.Close();
    }
}
