function elapsedTime(post: { date: Date }): string {
    const now = new Date();
    const diff = now.getTime() - post.date.getTime();
    const seconds = Math.floor(diff / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    let elapsed = '';
    if (days > 0) {
        elapsed += `${days} day${days > 1 ? 's' : ''} `;
    }
    if (hours > 0) {
        elapsed += `${hours % 24} hour${hours % 24 > 1 ? 's' : ''} `;
    }
    if (minutes > 0) {
        elapsed += `${minutes % 60} minute${minutes % 60 > 1 ? 's' : ''} `;
    }
    if (seconds > 0) {
        elapsed += `${seconds % 60} second${seconds % 60 > 1 ? 's' : ''}`;
    }

    return elapsed.trim();
}
